{
  "name": "task-manager",
  "version": "1.0.0",
  "description": "Small task management library for Frontier Verifier benchmark",
  "type": "module",
  "license": "MIT",
  "main": "src/index.ts",
  "scripts": {
    "test": "vitest run",
    "check-types": "tsc --noEmit"
  },
  "devDependencies": {
    "@types/bun": "latest"
  }
}

export type Priority = 1 | 2 | 3 | 4 | 5;
export type Status = "pending" | "in_progress" | "completed" | "archived";

export interface Task {
  id: string;
  title: string;
  description: string;
  priority: Priority;
  status: Status;
  dueDate: string | null; // ISO date string YYYY-MM-DD or null
  createdAt: string; // ISO timestamp
  updatedAt: string;
}

export interface CreateTaskInput {
  title: string;
  description?: string;
  priority: Priority;
  status?: Status;
  dueDate?: string | null;
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
  priority?: Priority;
  status?: Status;
  dueDate?: string | null;
}

import type { Task, CreateTaskInput, UpdateTaskInput, Status, Priority } from "./types.ts";
import { validatePriority, validateStatus, validateTitle, validateDueDate } from "./validators.ts";
import { generateId, isOverdue, toISOTimestamp } from "./utils.ts";

export class TaskManager {
  private tasks: Map<string, Task> = new Map();
  private statusCache: Map<Status, Task[]> | null = null;
  private cacheValid = false;

  createTask(input: CreateTaskInput): Task {
    validateTitle(input.title);
    validatePriority(input.priority);
    if (input.status !== undefined) validateStatus(input.status);
    if (input.dueDate !== undefined) validateDueDate(input.dueDate);

    const now = toISOTimestamp(new Date());
    const task: Task = {
      id: generateId(),
      title: input.title.trim(),
      description: input.description ?? "",
      priority: input.priority,
      status: input.status ?? "pending",
      dueDate: input.dueDate ?? null,
      createdAt: now,
      updatedAt: now,
    };
    this.tasks.set(task.id, task);
    this.invalidateCache();
    return { ...task };
  }

  updateTask(id: string, updates: UpdateTaskInput): Task {
    const existing = this.tasks.get(id);
    if (!existing) throw new Error(`Task not found: ${id}`);

    if (updates.title !== undefined) validateTitle(updates.title);
    if (updates.priority !== undefined) validatePriority(updates.priority);
    if (updates.status !== undefined) validateStatus(updates.status);
    if (updates.dueDate !== undefined) validateDueDate(updates.dueDate);

    // BUG: spreads undefined values and overwrites existing fields
    const updated: Task = {
      ...existing,
      title: updates.title as any,
      description: updates.description as any,
      priority: updates.priority as any,
      status: updates.status as any,
      dueDate: updates.dueDate as any,
      updatedAt: toISOTimestamp(new Date()),
    };
    // Remove undefined check - this will set fields to undefined if not provided
    // Simulate buggy behavior: if update field is undefined, it still overwrites
    // The above already does it. Need to ensure we don't preserve old values.
    // In JS, spreading with undefined overwrites: { ...existing, title: undefined } => title undefined
    this.tasks.set(id, updated as Task);
    this.invalidateCache();
    return { ...updated };
  }

  getTask(id: string): Task | undefined {
    const t = this.tasks.get(id);
    return t ? { ...t } : undefined;
  }

  listTasks(): Task[] {
    return Array.from(this.tasks.values()).map((t) => ({ ...t }));
  }

  deleteTask(id: string): void {
    if (!this.tasks.has(id)) throw new Error(`Task not found: ${id}`);
    this.tasks.delete(id);
    this.invalidateCache();
  }

  filterByStatus(status: Status): Task[] {
    validateStatus(status);
    if (this.cacheValid && this.statusCache?.has(status)) {
      return (this.statusCache.get(status) ?? []).map((t) => ({ ...t }));
    }
    const result = Array.from(this.tasks.values()).filter((t) => t.status === status);
    if (!this.statusCache) this.statusCache = new Map();
    if (!this.cacheValid) {
      this.rebuildCache();
    }
    return result.map((t) => ({ ...t }));
  }

  private rebuildCache(): void {
    this.statusCache = new Map();
    for (const task of this.tasks.values()) {
      const arr = this.statusCache.get(task.status) ?? [];
      arr.push({ ...task });
      this.statusCache.set(task.status, arr);
    }
    this.cacheValid = true;
  }

  private invalidateCache(): void {
    this.cacheValid = false;
    this.statusCache = null;
  }

  getOverdueTasks(now: Date = new Date()): Task[] {
    return Array.from(this.tasks.values()).filter((t) => isOverdue(t.dueDate, now, t.status));
  }

  getTasksByPriority(priority: Priority): Task[] {
    validatePriority(priority);
    return Array.from(this.tasks.values()).filter((t) => t.priority === priority);
  }

  clear(): void {
    this.tasks.clear();
    this.invalidateCache();
  }

  count(): number {
    return this.tasks.size;
  }
}

export * from "./types.ts";
export * from "./validators.ts";
export * from "./utils.ts";
export * from "./task-manager.ts";

import type { Priority, Status } from "./types.ts";

const VALID_PRIORITIES: Priority[] = [1, 2, 3, 4, 5];
const VALID_STATUSES: Status[] = ["pending", "in_progress", "completed", "archived"];

export function isValidPriority(value: unknown): value is Priority {
  return typeof value === "number" && VALID_PRIORITIES.includes(value as Priority);
}

export function isValidStatus(value: unknown): value is Status {
  return typeof value === "string" && (VALID_STATUSES as string[]).includes(value);
}

export function validatePriority(priority: unknown): void {
  if (!isValidPriority(priority)) {
    throw new Error(`Invalid priority: ${priority}. Must be integer 1-5.`);
  }
}

export function validateStatus(status: unknown): void {
  if (!isValidStatus(status)) {
    throw new Error(`Invalid status: ${status}`);
  }
}

export function validateTitle(title: unknown): void {
  if (typeof title !== "string" || title.trim().length === 0) {
    throw new Error("Title must be a non-empty string");
  }
  if (title.length > 200) {
    throw new Error("Title must be at most 200 characters");
  }
}

export function validateDueDate(dueDate: unknown): void {
  if (dueDate === null || dueDate === undefined) return;
  if (typeof dueDate !== "string") {
    throw new Error("dueDate must be string or null");
  }
  // Expect YYYY-MM-DD
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) {
    throw new Error(`Invalid dueDate format: ${dueDate}. Expected YYYY-MM-DD`);
  }
  const d = new Date(dueDate);
  if (isNaN(d.getTime())) {
    throw new Error(`Invalid dueDate value: ${dueDate}`);
  }
}

export function generateId(): string {
  return Math.random().toString(36).substring(2, 9);
}

export function toISODate(date: Date): string {
  return date.toISOString().split("T")[0]!;
}

export function toISOTimestamp(date: Date): string {
  return date.toISOString();
}

export function isOverdue(dueDate: string | null, now: Date, status: string): boolean {
  if (dueDate === null) return false;
  if (status === "completed" || status === "archived") return false;
  // Compare date strings as YYYY-MM-DD lexicographically == chronological
  const todayStr = toISODate(now);
  return dueDate < todayStr;
}

import { describe, test, expect } from "vitest";
import { TaskManager } from "../src/task-manager.ts";

describe("TaskManager", () => {
  test("createTask creates task with defaults", () => {
    const tm = new TaskManager();
    const t = tm.createTask({ title: "Test", priority: 3 });
    expect(t.title).toBe("Test");
    expect(t.priority).toBe(3);
    expect(t.status).toBe("pending");
    expect(t.dueDate).toBeNull();
  });

  test("createTask validates priority", () => {
    const tm = new TaskManager();
    expect(() => tm.createTask({ title: "x", priority: 0 as any })).toThrow();
    expect(() => tm.createTask({ title: "x", priority: 6 as any })).toThrow();
    expect(() => tm.createTask({ title: "x", priority: 3.5 as any })).toThrow();
  });

  test("createTask validates title", () => {
    const tm = new TaskManager();
    expect(() => tm.createTask({ title: "", priority: 3 })).toThrow();
    expect(() => tm.createTask({ title: "   ", priority: 3 })).toThrow();
  });

  test("updateTask merges correctly without losing fields", () => {
    const tm = new TaskManager();
    const t = tm.createTask({ title: "Orig", priority: 2, description: "desc" });
    const updated = tm.updateTask(t.id, { title: "Updated" });
    expect(updated.title).toBe("Updated");
    expect(updated.description).toBe("desc");
    expect(updated.priority).toBe(2);
  });

  test("updateTask only updates provided fields", () => {
    const tm = new TaskManager();
    const t = tm.createTask({ title: "t", priority: 1 });
    const u = tm.updateTask(t.id, { status: "completed" });
    expect(u.status).toBe("completed");
    expect(u.title).toBe("t");
    expect(u.priority).toBe(1);
  });

  test("getOverdueTasks detects overdue correctly", () => {
    const tm = new TaskManager();
    tm.createTask({ title: "overdue", priority: 1, dueDate: "2024-01-01" });
    tm.createTask({ title: "today", priority: 1, dueDate: "2024-06-15" });
    tm.createTask({ title: "future", priority: 1, dueDate: "2024-12-31" });
    tm.createTask({ title: "no due", priority: 1, dueDate: null });
    const now = new Date("2024-06-15T12:00:00Z");
    const overdue = tm.getOverdueTasks(now);
    expect(overdue.length).toBe(1);
    expect(overdue[0]!.title).toBe("overdue");
  });

  test("getOverdueTasks excludes completed tasks", () => {
    const tm = new TaskManager();
    tm.createTask({ title: "done overdue", priority: 1, dueDate: "2024-01-01", status: "completed" });
    const now = new Date("2024-06-15T12:00:00Z");
    expect(tm.getOverdueTasks(now).length).toBe(0);
  });

  test("filterByStatus returns correct tasks and not stale", () => {
    const tm = new TaskManager();
    tm.createTask({ title: "a", priority: 1, status: "pending" });
    tm.createTask({ title: "b", priority: 1, status: "completed" });
    let pending = tm.filterByStatus("pending");
    expect(pending.length).toBe(1);
    // add another pending and ensure cache invalidates
    tm.createTask({ title: "c", priority: 1, status: "pending" });
    pending = tm.filterByStatus("pending");
    expect(pending.length).toBe(2);
    // update status
    const t = pending[0]!;
    tm.updateTask(t.id, { status: "completed" });
    expect(tm.filterByStatus("pending").length).toBe(1);
    expect(tm.filterByStatus("completed").length).toBe(2);
  });

  test("filterByStatus validates status", () => {
    const tm = new TaskManager();
    expect(() => tm.filterByStatus("invalid" as any)).toThrow();
  });

  test("getTasksByPriority filters correctly", () => {
    const tm = new TaskManager();
    tm.createTask({ title: "p1", priority: 1 });
    tm.createTask({ title: "p5", priority: 5 });
    expect(tm.getTasksByPriority(1).length).toBe(1);
    expect(tm.getTasksByPriority(5).length).toBe(1);
  });

  test("deleteTask removes task", () => {
    const tm = new TaskManager();
    const t = tm.createTask({ title: "del", priority: 1 });
    tm.deleteTask(t.id);
    expect(tm.getTask(t.id)).toBeUndefined();
    expect(tm.count()).toBe(0);
  });
});

