import { TaskManager } from "./src/task-manager.ts";

const tm = new TaskManager();

// Create a task with all fields set
const t = tm.createTask({
  title: "Original Title",
  description: "Original Description",
  priority: 3,
  status: "in_progress",
  dueDate: "2025-12-31",
});

console.log("=== Original Task ===");
console.log(JSON.stringify(t, null, 2));

// Update only title — all other fields should remain unchanged
const updated = tm.updateTask(t.id, { title: "New Title" });

console.log("\n=== After Update (only title) ===");
console.log(JSON.stringify(updated, null, 2));

// Verify fields are preserved
let failures = 0;

if (updated.title !== "New Title") {
  console.error(`FAIL: title expected "New Title", got "${updated.title}"`);
  failures++;
}
if (updated.description !== "Original Description") {
  console.error(`FAIL: description expected "Original Description", got "${updated.description}"`);
  failures++;
}
if (updated.priority !== 3) {
  console.error(`FAIL: priority expected 3, got ${updated.priority}`);
  failures++;
}
if (updated.status !== "in_progress") {
  console.error(`FAIL: status expected "in_progress", got "${updated.status}"`);
  failures++;
}
if (updated.dueDate !== "2025-12-31") {
  console.error(`FAIL: dueDate expected "2025-12-31", got "${updated.dueDate}"`);
  failures++;
}

if (failures === 0) {
  console.log("\n✅ All fields preserved correctly — bug is fixed!");
} else {
  console.error(`\n❌ ${failures} field(s) were erased by the update.`);
  process.exit(1);
}

