import { describe, test, expect } from "vitest";
import { TaskManager } from "../src/task-manager.ts";

describe("UpdateTask invariants", () => {
  test("updating only title preserves description, priority, status, dueDate", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "A",
      description: "desc",
      priority: 4,
      status: "in_progress",
      dueDate: "2025-06-01",
    });
    const u = tm.updateTask(t.id, { title: "B" });
    expect(u.title).toBe("B");
    expect(u.description).toBe("desc");
    expect(u.priority).toBe(4);
    expect(u.status).toBe("in_progress");
    expect(u.dueDate).toBe("2025-06-01");
  });

  test("updating only priority preserves all other fields", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "X",
      description: "some desc",
      priority: 1,
      dueDate: "2025-12-25",
    });
    const u = tm.updateTask(t.id, { priority: 5 });
    expect(u.priority).toBe(5);
    expect(u.title).toBe("X");
    expect(u.description).toBe("some desc");
    expect(u.dueDate).toBe("2025-12-25");
    expect(u.status).toBe("pending");
  });

  test("updating only status preserves all other fields", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "Y",
      priority: 2,
      status: "pending",
    });
    const u = tm.updateTask(t.id, { status: "completed" });
    expect(u.status).toBe("completed");
    expect(u.title).toBe("Y");
    expect(u.priority).toBe(2);
  });

  test("setting dueDate to null clears dueDate but preserves rest", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "Z",
      priority: 3,
      dueDate: "2025-08-15",
    });
    const u = tm.updateTask(t.id, { dueDate: null });
    expect(u.dueDate).toBeNull();
    expect(u.title).toBe("Z");
    expect(u.priority).toBe(3);
  });

  test("empty update object leaves task unchanged except updatedAt", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "unchanged",
      description: "unchanged desc",
      priority: 2,
      status: "in_progress",
      dueDate: "2025-03-10",
    });
    const u = tm.updateTask(t.id, {});
    expect(u.title).toBe("unchanged");
    expect(u.description).toBe("unchanged desc");
    expect(u.priority).toBe(2);
    expect(u.status).toBe("in_progress");
    expect(u.dueDate).toBe("2025-03-10");
    expect(u.id).toBe(t.id);
    expect(u.createdAt).toBe(t.createdAt);
    // updatedAt should be refreshed
    expect(u.updatedAt).not.toBe(t.updatedAt);
  });

  test("updating all fields at once works correctly", () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "old",
      description: "old desc",
      priority: 1,
      status: "pending",
      dueDate: "2025-01-01",
    });
    const u = tm.updateTask(t.id, {
      title: "new",
      description: "new desc",
      priority: 5,
      status: "archived",
      dueDate: "2025-12-31",
    });
    expect(u.title).toBe("new");
    expect(u.description).toBe("new desc");
    expect(u.priority).toBe(5);
    expect(u.status).toBe("archived");
    expect(u.dueDate).toBe("2025-12-31");
  });

  test("concurrent updates on same task do not cross-contaminate", async () => {
    const tm = new TaskManager();
    const t = tm.createTask({
      title: "concurrent",
      priority: 1,
      description: "base",
    });

    // Fire updates in parallel via microtasks
    const [u1, u2] = await Promise.all([
      Promise.resolve().then(() => tm.updateTask(t.id, { title: "from-1" })),
      Promise.resolve().then(() => tm.updateTask(t.id, { priority: 5 })),
    ]);

    // After both resolve, the stored task should have both updates applied
    const final = tm.getTask(t.id)!;
    // One of the two updates won — both title and priority should be non-undefined
    expect(typeof final.title).toBe("string");
    expect(typeof final.priority).toBe("number");
    expect(final.description).toBe("base");
  });

  test("updating non-existent task throws", () => {
    const tm = new TaskManager();
    expect(() => tm.updateTask("nonexistent", { title: "x" })).toThrow("Task not found");
  });

  test("update does not mutate original object returned by createTask", () => {
    const tm = new TaskManager();
    const t = tm.createTask({ title: "orig", priority: 1 });
    tm.updateTask(t.id, { title: "mutated" });
    // The original reference should still hold the old value
    expect(t.title).toBe("orig");
  });

  test("filterByStatus cache is consistent after update", () => {
    const tm = new TaskManager();
    tm.createTask({ title: "p1", priority: 1, status: "pending" });
    tm.createTask({ title: "p2", priority: 1, status: "completed" });

    // Warm cache
    expect(tm.filterByStatus("pending").length).toBe(1);

    // Update a pending → completed
    const pending = tm.filterByStatus("pending");
    tm.updateTask(pending[0]!.id, { status: "completed" });

    expect(tm.filterByStatus("pending").length).toBe(0);
    expect(tm.filterByStatus("completed").length).toBe(2);
  });
});

